export function balancedSectionIndex(groups:Fragment[][],limit=2000):Fragment[]{
 const available=groups.filter(group=>group.length),total=available.reduce((sum,group)=>sum+group.length,0),target=Math.min(Math.max(0,limit),total);
 if(!target)return[];if(total<=target)return available.flat();
 const quotas=available.map(()=>0);let remaining=target;
 while(remaining){const candidates=available.map((group,index)=>({group,index})).filter(({group,index})=>quotas[index]<group.length);if(!candidates.length)break;const share=Math.max(1,Math.floor(remaining/candidates.length));for(const {group,index} of candidates){if(!remaining)break;const take=Math.min(share,group.length-quotas[index],remaining);quotas[index]+=take;remaining-=take;}}
 return available.flatMap((group,index)=>{const count=quotas[index];if(!count)return[];if(count>=group.length)return group;if(count===1)return[group[0]];return Array.from({length:count},(_,position)=>group[Math.round(position*(group.length-1)/(count-1))]);});
}

