  if(this.mainlineRevision(projectId)!==revision)return false;if(!unit)return true;const project=this.requireProject(projectId),current=this.store.get('learningUnits',unit.id);return !!current&&current.projectId===projectId&&current.routeVersionId===unit.routeVersionId&&current.capabilityId===unit.capabilityId&&current.status!=='retired'&&(!project.activeRouteVersionId||project.activeRouteVersionId===unit.routeVersionId);
